INSERT INTO `currency_types_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3356, 'esES', 'Cristales de maná incólumes', 'Se puede conseguir tras alcanzar el rango 9 del viaje de explorador de profundidades. Se puede obtener al abrir arcas pródigas con llaves de arca restauradas dentro de las profundidades pródigas de nivel 11. Se le puede cambiar a Zah\'ran por equipo poderoso.', 69497),
(3418, 'esES', 'Núcleo de Vacío nebuloso', 'Se puede transmutar en equipo de gran poder tras derrotar a enemigos peligrosos en bandas de Midnight o completar mazmorras míticas+, profundidades pródigas y cacerías de Presa en dificultad pesadilla.\n\nPuedes recibir los objetos una vez por dificultad hasta que hayas transmutado todos los objetos posibles para tu especialización actual.', 69497),
(3509, 'esES', 'Polvo de chispa de las mareas', 'Residuo mágico obtenido junto a las chispas de las mareas. Sirven para saber cuántas chispas de las mareas has obtenido hasta ahora durante la temporada 2 de Midnight.\n\nSi no has obtenido todas las chispas de las mareas disponibles, podrás ponerte al día completando contenido de nivel máximo, como profundidades, mazmorras míticas+, bandas, JcJ instanciado o algunos eventos del mundo abierto.', 69497);
