(36417, 'esES', 'Avatar de Sethraliss', 'La batalla concluye con la restauración completa del avatar de Sethraliss.', 69497),
(36416, 'esES', 'Sección 18', '', 69497),
(18515, 'esES', 'Sección 14', '$[!8,23\n\nEn dificultad mítica, se forman varios orbes de |cFF2959D3|Hspell:1300871|h[Fuerza vital corrupta]|h|r.\n$]', 69497),
(18514, 'esES', '', '', 69497),
(18513, 'esES', 'Aojador retorcido', '', 69497),
