INSERT INTO `scenario_step_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `VerifiedBuild`) VALUES
(17053, 'esES', 'Adéntrate en las cámaras malditas bajo el Sello de la Cólera y elimina las amenazas de su interior.', 'Limpia las Zonas Profundas Malditas', 69497),
(17052, 'esES', 'Encuentra la forma de entrar en las Zonas Profundas Malditas.', 'Accede a las Zonas Profundas Malditas', 69497),
(17048, 'esES', 'Prepárate para atacar los Bajos Fondos.', 'Prepara el ataque', 69497),
(17044, 'esES', 'Entra en los Bajos Fondos y derrota a los enemigos que hay allí.', 'Limpia los Bajos Fondos', 69497),
(17032, 'esES', 'Prepárate. Se alza una marea de sierpes.', 'Serpenteos de las profundidades', 69497),
(17030, 'esES', 'Los cuidallamas están preparando las piras espirituales.', 'Prepara las piras', 69497),
(17028, 'esES', '¡Se ha descubierto un extraño alijo!', 'Examina el alijo', 69497),
(16919, 'esES', 'Entra en varios portales y destruye huevos de Ruuk\'Jar.', 'Destruye la nidada', 69497),
(16918, 'esES', 'Espera a que se abra el portal.', 'Invoca el portal', 69497),
(16876, 'esES', 'Alijo desbloqueado.', 'Alijo desbloqueado', 69497),
(16875, 'esES', 'Lleva los tres báculos de cada piedra al alijo.', 'Recupera los báculos', 69497),
(16873, 'esES', 'Reúne espíritus perversos y quémalos en piras espirituales. Lleva llamas a las piras para destruir los sarcófagos profanados.', 'Purga a los no-muertos', 69497),
(16858, 'esES', 'Usa los santuarios para conseguir orbes de impureza.', 'Usa los Santuarios de Tierra y Cielo', 69497),
(16856, 'esES', 'Asesina sierpes e interrumpe rituales antes de que invadan el templo.', 'Frena la marea de sierpes', 69497),
(16853, 'esES', 'Los santuarios se están potenciando para su uso.', 'Potencia los santuarios', 69497),
(17336, 'esES', 'Ábrete paso hasta el corazón del Abismo Venenoso y evita que Ula\'tek escape de su prisión.', 'Tumba de Ula\'tek', 69497),
(17329, 'esES', 'Ábrete paso hasta el corazón del Abismo Venenoso y enfréntate cara a cara a Ula\'tek.', 'Tumba de Ula\'tek', 69497),
(17328, 'esES', 'Las salas ancestrales que guardan las tumbas de las víctimas de los Volutadores de Almas ahora están habitadas por serpientes monstruosas.', 'Escondrijo de la Sierpe', 69497),
(17327, 'esES', 'En el interior de la Cámara de la Virulencia, Vashnik el Maligno destila los venenos de Ula\'tek y los convierte en formas aún más letales.', 'La esencia del veneno', 69497);
